import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val t = 1
    repeat(t) {
        val n = scanner.nextLong()
        val k = scanner.nextLong()
        var l = -1L
        var r = n + 1
        while (r - l > 1) {
            val m = (l + r) / 2
            if ((n - m) * (n - m + 1) / 2 - m > k) {
                l = m
            } else {
                r = m
            }
        }
        println(r)
    }
}

